func nextPermutation(nums []int) {
    n := len(nums)
    // 从右向左找第一个下降点
    i := n - 2
    for i >= 0 && nums[i] >= nums[i+1] {
        i--
    }
    if i >= 0 {
        // 从右向左找第一个大于 nums[i] 的数
        j := n - 1
        for nums[j] <= nums[i] {
            j--
        }
        nums[i], nums[j] = nums[j], nums[i]
    }
    // 反转 i+1 到末尾
    lo, hi := i+1, n-1
    for lo < hi {
        nums[lo], nums[hi] = nums[hi], nums[lo]
        lo++
        hi--
    }
}
